BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email) SELECT ('ac100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'privacy-'||n||'@local.test' FROM generate_series(1,3)n;
INSERT INTO public.users(id,auth_id,username,role,name) SELECT ('ac100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('ac100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'privacy_'||n,(ARRAY['admin','designer','designer'])[n],'Privacy '||n FROM generate_series(1,3)n;
INSERT INTO public.suppliers(id,name,phone) VALUES('ac100000-0000-4000-8000-000000000010','Hidden Supplier','01000000001');
INSERT INTO public.doctors(id,name,phone,address,doctor_code,representative_name) VALUES('ac100000-0000-4000-8000-000000000011','Hidden Doctor','01000000000','QA','PRIV-QA','QA');
INSERT INTO public.orders(id,case_id,doctor_id,patient_name,items,total_price,cost,shade,production_status,delivery_date,workflow_type,designer_id,supplier_id,design_price)
VALUES('ac100000-0000-4000-8000-000000000012','PRIV-CASE','ac100000-0000-4000-8000-000000000011','Technical patient','[]',999,777,'A1','designing',current_date,'split','ac100000-0000-4000-8000-000000000002','ac100000-0000-4000-8000-000000000010',123);
INSERT INTO storage.objects(bucket_id,name) VALUES('case-scans','ac100000-0000-4000-8000-000000000012/instruction/scan.stl'),('case-scans','ac100000-0000-4000-8000-000000000099/instruction/private.stl');
SELECT set_config('request.jwt.claim.sub','ac100000-0000-4000-8000-000000000002',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.orders),0::bigint,'Designer raw order API cannot expose commercial columns');
SELECT is((SELECT count(*) FROM public.suppliers),0::bigint,'Designer raw supplier API hides identity');
SELECT is((SELECT count(*) FROM public.doctors),0::bigint,'Designer raw doctor API hides accounts');
SELECT is((SELECT count(*) FROM public.users),1::bigint,'Designer cannot list other staff financial profiles');
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='case-scans'),1::bigint,'Designer can read only assigned case scan metadata');
SELECT is(public.get_designer_workspace(NULL,false)->0->>'patient_name','Technical patient','Technical projection retains assigned case');
SELECT ok(NOT(public.get_designer_workspace(NULL,false)->0 ?| ARRAY['supplier_id','doctor_id','total_price','cost','lab_cost','accounting_snapshot']),'Safe projection omits commercial keys rather than returning hidden values');
SELECT is((public.get_designer_workspace(NULL,true)->0->>'design_price')::numeric,123::numeric,'Personal finance projection preserves own fee');
SELECT throws_ok($$SELECT public.update_designer_workspace('ac100000-0000-4000-8000-000000000012','{"total_price":1}',NULL)$$,'42501','Designer field denied','Scoped write rejects money changes');
SELECT lives_ok($$SELECT public.update_designer_workspace('ac100000-0000-4000-8000-000000000012','{"technician_status":"Approved"}',NULL)$$,'Scoped write preserves designer acceptance');
RESET ROLE;
INSERT INTO public.app_settings(key,value) VALUES('workflow_issue_v2_write','on') ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value;
SELECT public.request_designer_rejection_v2('ac100000-0000-4000-8000-000000000012','Technical rejection reason','ac100000-0000-4000-8000-000000000050',NULL,NULL);
SELECT ok(public.get_designer_workspace('ac100000-0000-4000-8000-000000000012',false)::text LIKE '%Technical rejection reason%','Designer rejection reason remains in scoped technical history');
SELECT is((SELECT total_price FROM public.orders WHERE id='ac100000-0000-4000-8000-000000000012'),999::numeric,'Technical writes do not touch selling price');
SELECT is((SELECT cost FROM public.orders WHERE id='ac100000-0000-4000-8000-000000000012'),777::numeric,'Technical writes do not touch laboratory cost');
SELECT set_config('request.jwt.claim.sub','ac100000-0000-4000-8000-000000000003',true);
SELECT is(public.get_designer_workspace('ac100000-0000-4000-8000-000000000012',false),'[]'::jsonb,'Unassigned designer gets no case');
SELECT throws_ok($$SELECT public.update_designer_workspace('ac100000-0000-4000-8000-000000000012','{"technician_status":"Approved"}',NULL)$$,'42501','Design access denied','Unassigned designer cannot write');
SELECT set_config('request.jwt.claim.sub','ac100000-0000-4000-8000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT total_price FROM public.orders WHERE id='ac100000-0000-4000-8000-000000000012'),999::numeric,'Admin keeps full authorized order read');
RESET ROLE;
UPDATE public.orders SET designer_id='ac100000-0000-4000-8000-000000000003' WHERE id='ac100000-0000-4000-8000-000000000012';
SELECT set_config('request.jwt.claim.sub','ac100000-0000-4000-8000-000000000002',true);
SELECT is(public.get_designer_workspace(NULL,false),'[]'::jsonb,'Former designer loses technical case after assignment change');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='case-scans'),0::bigint,'Former designer cannot sign or list previous case scans');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
